package com.henson.jarvis.phone;
import ai.onnxruntime.*;import android.content.Context;import org.json.*;import java.io.*;import java.nio.*;import java.util.*;
public final class NativeSpeech implements AutoCloseable {
 private final Context context;private final LocalSite site;private OrtEnvironment env;private OrtSession session;
 public NativeSpeech(Context context,LocalSite site){this.context=context.getApplicationContext();this.site=site;}
 private void load()throws Exception{if(session!=null)return;File model=new File(context.getFilesDir(),"kokoro-v1-q8.onnx");if(!model.isFile()){File temp=new File(context.getFilesDir(),"kokoro-v1-q8.tmp");try(InputStream in=context.getAssets().open("site/models/kokoro/onnx/model_quantized.onnx");OutputStream out=new FileOutputStream(temp)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}if(!temp.renameTo(model))throw new IOException("Could not prepare the bundled male voice.");}env=OrtEnvironment.getEnvironment();try(OrtSession.SessionOptions options=new OrtSession.SessionOptions()){options.setIntraOpNumThreads(2);options.setInterOpNumThreads(1);options.setOptimizationLevel(OrtSession.SessionOptions.OptLevel.ALL_OPT);options.addConfigEntry("session.intra_op.allow_spinning","0");session=env.createSession(model.getAbsolutePath(),options);}}
 public synchronized JSONObject generate(JSONObject body)throws Exception{long start=android.os.SystemClock.elapsedRealtime();JSONArray ids=body.getJSONArray("input_ids"),style=body.getJSONArray("style");double speed=body.optDouble("speed",0.94);if(ids.length()<1||ids.length()>512||style.length()!=256||!Double.isFinite(speed)||speed<0.5||speed>2)throw new Exception("Invalid local speech request.");long[][] input=new long[1][ids.length()];for(int i=0;i<ids.length();i++)input[0][i]=ids.getLong(i);float[][] voice=new float[1][256];for(int i=0;i<256;i++){double value=style.getDouble(i);if(!Double.isFinite(value))throw new Exception("Invalid speech style.");voice[0][i]=(float)value;}load();long inferenceStart=android.os.SystemClock.elapsedRealtime();try(OnnxTensor tokens=OnnxTensor.createTensor(env,input);OnnxTensor speaker=OnnxTensor.createTensor(env,voice);OnnxTensor pace=OnnxTensor.createTensor(env,new float[]{(float)speed})){Map<String,OnnxTensor> feed=new HashMap<>();feed.put("input_ids",tokens);feed.put("style",speaker);feed.put("speed",pace);try(OrtSession.Result result=session.run(feed)){OnnxTensor audio=(OnnxTensor)result.get(0);FloatBuffer samples=audio.getFloatBuffer();if(samples==null||samples.remaining()<1||samples.remaining()>24000*40)throw new Exception("Invalid generated audio.");int count=samples.remaining();ByteBuffer bytes=ByteBuffer.allocate(count*4).order(ByteOrder.LITTLE_ENDIAN);bytes.asFloatBuffer().put(samples);String url=site.addAudio(bytes.array());android.util.Log.i("JarvisTiming","Native male voice: inferenceMs="+(android.os.SystemClock.elapsedRealtime()-inferenceStart)+" totalMs="+(android.os.SystemClock.elapsedRealtime()-start)+" audioMs="+(count/24));return new JSONObject().put("url",url).put("rate",24000).put("samples",count).put("backend","onnx-native").put("inferenceMs",android.os.SystemClock.elapsedRealtime()-inferenceStart).put("totalMs",android.os.SystemClock.elapsedRealtime()-start);}}}
 public synchronized void close(){if(session!=null)try{session.close();}catch(Exception ignored){}session=null;}
}
